MORE.update({'nikola-lenivets': {'hist': ['Всё началось с художника Николая Полисского: он поселился в деревне Никола-Ленивец и начал строить арт-объекты вместе с местными жителями. Первый постоянный объект, «Маяк», появился в 2004 году.', 'С тех пор здесь проходит фестиваль ландшафтной архитектуры «Архстояние», и каждый год в парке прибавляются новые работы. Сейчас их больше пятидесяти.'], 'extra': [('Жар-птица', 'Металлическая птица Полисского, 2008 год.'), ('Орган и Баня-форум', 'Новые объекты 2024–2025 годов.'), ('Сельпо', 'Бывший сельский магазин, превращённый Полисским в арт-объект в 2015 году.')], 'food': [], 'hsrc': []}, 'etnomir': {'hist': [], 'extra': [('Парк птиц «Воробьи»', 'В том же направлении — можно совместить за выходные.'), ('Боровск', 'Старый город с монастырём неподалёку.')], 'food': [], 'hsrc': []}, 'kochevnik': {'hist': ['Этнопарк основал в 2012 году Алексей Ежелев, который до этого занимался продажей юрт. О быте кочевников здесь рассказывают в том числе представители самих кочевых народов.'], 'extra': [('Вертолёт Ми-8', 'Стоит на экспозиции «Транспорт Севера».')], 'food': [], 'hsrc': [('KudaGo: этнопарк «Кочевник»', 'https://kudago.com/msk/place/etnopark-kochevnik/')]}, 'vorobi': {'hist': [], 'extra': [('Этномир', 'Примерно в получасе езды — вторая точка на выходные.')], 'food': [], 'hsrc': []}})

