def hub():
    title = 'За город: куда поехать из Москвы на день или выходные'
    desc = 'Места в пределах дня пути от Москвы: как добраться на электричке и машине, маршрут на день, где поесть. Сергиев Посад, Коломна, Звенигород, Новый Иерусалим, усадьбы Архангельское, Абрамцево и Мелихово.'
    out = head(title, desc, f'{BASE}/zagorod/', '../')
    out += f'''<main class="wrap">
  <header class="hero has-art"><div class="hero-copy"><p class="eyebrow">Атлас Москвы · выезд на день</p><h1>За город</h1><p>Куда съездить из Москвы на день или на выходные: как добраться, что посмотреть по порядку, где поесть. Арт-парки, этнопарки, города и усадьбы в пределах дня пути — места будут добавляться.</p></div>{ART["hub"]}</header>
  <section class="zg-sec"><h2>На карте</h2><div id="zgmap" aria-label="Карта мест за городом"></div></section>
  <section class="zg-sec"><h2>Модное и с детьми</h2><div class="zg-grid">{''.join(card(p, '') for p in PLACES if p.get('fun'))}</div></section>
  <section class="zg-sec"><h2>Города, монастыри и усадьбы</h2><div class="zg-grid">{''.join(card(p, '') for p in PLACES if not p.get('fun'))}</div></section>
  <footer class="zg-src">Проверено {CHECKED}. У каждого места — источники фактов. Карта — <a href="https://www.openstreetmap.org/copyright">© OpenStreetMap</a>.</footer>
</main>
{map_js([(p['name'], *HUBPT[p['slug']], p['km'] + ' · ' + p['kind'], p['slug'] + '/') for p in PLACES], False)}
{METRIKA}
</body>
</html>
'''
    return out

os.makedirs(f'{REPO}/zagorod', exist_ok=True)
open(f'{REPO}/zagorod/index.html', 'w', encoding='utf-8').write(hub())
for p in PLACES:
    os.makedirs(f'{REPO}/zagorod/{p["slug"]}', exist_ok=True)
    open(f'{REPO}/zagorod/{p["slug"]}/index.html', 'w', encoding='utf-8').write(place_page(p))

# «За город» — отдельная заметная кнопка справа в шапке всех страниц (не вкладка в общем ряду). Идемпотентно.
ICON = ('<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
        '<circle cx="16.5" cy="7" r="3"/><path d="M2 19c3.5-5 7-5 10-2.5 2.5-2 6-2.5 10 2.5M7 19l3-9 3 9"/></svg>')
n = 0
for f in glob.glob(f'{REPO}/**/*.html', recursive=True):
    if '/node_modules/' in f: continue
    s0 = open(f, encoding='utf-8').read(); t = s0
    t = re.sub(r'<a href="[^"]*zagorod/"( aria-current="page")?>За город</a>', '', t)          # старый пункт в ряду вкладок
    t = re.sub(r'<a class="go-out"[^>]*>.*?</a>', '', t, flags=re.S)
    m = re.search(r'<a href="([^"]*)parks\.html"', t)
    if '<nav class="tabs"' not in t or not m: continue
    pre = m.group(1); cur = ' aria-current="page"' if '/zagorod/' in f else ''
    i = t.index('</nav>', t.index('<nav class="tabs"')) + len('</nav>')
    t = t[:i] + f'<a class="go-out" href="{pre}zagorod/"{cur}>{ICON}<span>За город</span></a>' + t[i:]
    if t != s0: open(f, 'w', encoding='utf-8').write(t); n += 1
g = f'{REPO}/tools/build_park_pages.py'; gs = open(g, encoding='utf-8').read()
gs = gs.replace('<a href="../../zagorod/">За город</a>', '')
open(g, 'w', encoding='utf-8').write(gs)
# sitemap
sm = open(f'{REPO}/sitemap.xml', encoding='utf-8').read()
sm = re.sub(r'  <url><loc>' + re.escape(BASE) + r'/zagorod/[^<]*</loc>.*?</url>\n', '', sm)
today = datetime.date.today().isoformat()
urls = [f'{BASE}/zagorod/'] + [f'{BASE}/zagorod/{p["slug"]}/' for p in PLACES]
sm = sm.replace('</urlset>', ''.join(f'  <url><loc>{u}</loc><lastmod>{today}</lastmod></url>\n' for u in urls) + '</urlset>')
open(f'{REPO}/sitemap.xml', 'w', encoding='utf-8').write(sm)
print('страниц «За город»:', 1 + len(PLACES), '· кнопка обновлена на', n, 'страницах')
